import { z } from 'zod'

// Session ids are generated by crypto.randomUUID() in useSessionId.ts. They act
// as a bearer token for a browser's documents, so only real UUIDs are accepted.
export const sessionIdSchema = z.string().uuid('session_id must be a valid UUID')

// Document ids are bigint primary keys: digits only.
const documentIdStringSchema = z.string().regex(/^\d+$/, 'Document id must be a number')

export const chatMessageSchema = z.object({
  role: z.enum(['user', 'assistant']),
  content: z
    .string()
    .min(1, 'Message content cannot be empty')
    .max(20000, 'Message content is too long'),
})

export const chatRequestSchema = z.object({
  messages: z.array(chatMessageSchema).min(1, 'At least one message is required'),
  selectedDocIds: z
    .array(z.union([z.string(), z.number()]).transform(val => String(val)))
    .max(50, 'Too many documents selected')
    .default([]),
  session_id: sessionIdSchema,
})

export const evalRequestSchema = z.object({
  session_id: sessionIdSchema,
  document_id: z.union([z.string(), z.number()]).transform(val => String(val)),
})

export const documentsDeleteSchema = z.object({
  id: documentIdStringSchema,
})

export const documentsQuerySchema = z.object({
  session_id: sessionIdSchema,
})

export const uploadFieldsSchema = z.object({
  session_id: sessionIdSchema,
})

export function formatZodError(error: z.ZodError): string {
  return error.issues
    .map(issue => `${issue.path.join('.') || 'body'}: ${issue.message}`)
    .join('; ')
}